const input = $input.first().json;

if (!input || !input.data || input.data.length === 0) {
  throw new Error('❌ No data from Facebook API');
}

console.log(`📊 Received ${input.data.length} days of data`);

const projectId = '64c94e87-630c-470e-8ab1-8f7c8c835efa';

function safeParse(value, decimals = 2) {
  const num = parseFloat(value || 0);
  return isNaN(num) ? 0 : parseFloat(num.toFixed(decimals));
}

function safeInt(value) {
  const num = parseInt(value || 0, 10);
  return isNaN(num) ? 0 : num;
}

function extractAction(actions, actionTypes) {
  if (!actions || !Array.isArray(actions)) return 0;

  for (const type of actionTypes) {
    const action = actions.find(a => a.action_type === type);
    if (action) return safeInt(action.value);
  }
  return 0;
}

const results = input.data.map(fbData => {
  const leads = extractAction(fbData.actions, [
    'lead',
    'leadgen_grouped',
    'onsite_conversion.lead_grouped'
  ]);

  const conversations = extractAction(fbData.actions, [
    'onsite_conversion.messaging_conversation_started_7d',
    'onsite_conversion.messaging_first_reply',
    'onsite_conversion.post_save',
    'onsite_conversion.messaging_conversation_started_1d'
  ]);

  const result = {
    project_id: projectId,
    date: fbData.date_start,
    spend: safeParse(fbData.spend, 2),
    impressions: safeInt(fbData.impressions),
    clicks: safeInt(fbData.clicks),
    reach: safeInt(fbData.reach),
    ctr: safeParse(fbData.ctr, 4),
    cpc: safeParse(fbData.cpc, 2),
    cpm: safeParse(fbData.cpm, 2),
    leads: leads,
    conversations: conversations,
    source: 'facebook_ads',
    account_id: 'act_1005197113823722'
  };

  console.log(`✅ ${result.date}: spend=${result.spend}, leads=${result.leads}, conversations=${result.conversations}`);

  return result;
});

console.log(`\n🎉 Total: ${results.length} days transformed`);

return results.map(r => ({ json: r }));

const items = $input.all();

const totalDays = items.length;
const totalSpend = items.reduce((sum, item) => sum + (item.json.spend || 0), 0);
const totalLeads = items.reduce((sum, item) => sum + (item.json.leads || 0), 0);
const totalConversations = items.reduce((sum, item) => sum + (item.json.conversations || 0), 0);
const totalImpressions = items.reduce((sum, item) => sum + (item.json.impressions || 0), 0);
const totalClicks = items.reduce((sum, item) => sum + (item.json.clicks || 0), 0);

const result = {
  success: true,
  imported_days: totalDays,
  total_spend: totalSpend.toFixed(2) + ' ₸',
  total_impressions: totalImpressions.toLocaleString(),
  total_clicks: totalClicks.toLocaleString(),
  total_leads: totalLeads,
  total_conversations: totalConversations,
  message: `✅ УСПЕШНО ИМПОРТИРОВАНО ${totalDays} ДНЕЙ!`,
  details: {
    spend: `${totalSpend.toFixed(2)} ₸`,
    leads: totalLeads,
    conversations: totalConversations,
    cpl: totalLeads > 0 ? `${(totalSpend / totalLeads).toFixed(2)} ₸` : 'N/A',
    cpc: totalClicks > 0 ? `${(totalSpend / totalClicks).toFixed(2)} ₸` : 'N/A'
  }
};

console.log('\n🎉 IMPORT COMPLETE!');
console.log('===================');
console.log(`Days imported: ${totalDays}`);
console.log(`Total spend: ${result.total_spend}`);
console.log(`Total leads: ${totalLeads}`);
console.log(`Total conversations: ${totalConversations}`);
console.log(`CPL: ${result.details.cpl}`);
console.log('===================\n');

return { json: result };
